package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;
import android.os.*;import android.view.*;import android.widget.*;import android.text.InputType;
import java.io.*;

/** Local raster PDF reader. One bounded bitmap; no claim of PDF text extraction. */
public final class PdfReaderActivity extends LeoActivity {
    private File file;private String key;private int page,count,zoom=1;private volatile int generation;
    private Bitmap bitmap;private View canvas;private float panX,panY;private boolean closed;
    static int[] dimensions(int width,int height){if(width<=0||height<=0)throw new IllegalArgumentException();double scale=Math.min(2.0,Math.min(1024.0/width,1536.0/height));scale=Math.min(scale,Math.sqrt(1048576.0/width/height));return new int[]{Math.max(1,(int)(width*scale)),Math.max(1,(int)(height*scale))};}
    protected void onCreate(Bundle b){super.onCreate(b);try{file=new File(getIntent().getStringExtra("file"));if(!ReaderActivity.allowed(this,file)||file.length()>32L*1048576)throw new IOException();key=BackupEngine.hash((file.getCanonicalPath()+"|"+file.length()+"|"+file.lastModified()).getBytes("UTF-8"));page=Math.max(0,getSharedPreferences("pdf-reader",0).getInt(key,0));render();}catch(Exception e){notice(L.t("PDF inaccesibil sau peste 32 MiB"));finish();}}
    private void save(){if(key!=null&&count>0){getSharedPreferences("pdf-reader",0).edit().putInt(key,page).apply();getSharedPreferences("reader",0).edit().putString("last",file.getAbsolutePath()).apply();}}
    private void render(){final int token=++generation,wanted=page;begin(L.t("PDF · se încarcă"));root.addView(text(L.t("Se încarcă…"),17));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){Bitmap image=null;try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd)){final int total=pdf.getPageCount();if(total<=0||total>10000)throw new IOException();final int actual=Math.min(wanted,total-1);try(PdfRenderer.Page p=pdf.openPage(actual)){int[] size=dimensions(p.getWidth(),p.getHeight());image=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);image.eraseColor(Color.WHITE);p.render(image,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}final Bitmap ready=image;image=null;runOnUiThread(new Runnable(){public void run(){if(closed||token!=generation){ready.recycle();return;}if(bitmap!=null)bitmap.recycle();bitmap=ready;page=actual;count=total;zoom=1;panX=panY=0;save();show();}});}catch(Exception|OutOfMemoryError e){if(image!=null)image.recycle();ui(new Runnable(){public void run(){if(token==generation){notice(L.t("PDF corupt, protejat sau nesuportat"));finish();}}});}}});}
    private void show(){begin(L.t("PDF · ")+(page+1)+" / "+count);canvas=new View(this){private final Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);protected void onDraw(Canvas c){c.drawColor(0xff202329);if(bitmap==null)return;float fit=Math.min(getWidth()/(float)bitmap.getWidth(),getHeight()/(float)bitmap.getHeight())*zoom;float w=bitmap.getWidth()*fit,h=bitmap.getHeight()*fit;panX=Math.max(-Math.max(0,(w-getWidth())/2),Math.min(Math.max(0,(w-getWidth())/2),panX));panY=Math.max(-Math.max(0,(h-getHeight())/2),Math.min(Math.max(0,(h-getHeight())/2),panY));c.drawBitmap(bitmap,null,new RectF((getWidth()-w)/2+panX,(getHeight()-h)/2+panY,(getWidth()+w)/2+panX,(getHeight()+h)/2+panY),paint);}};root.addView(canvas,new LinearLayout.LayoutParams(-1,0,1));canvas.setFocusableInTouchMode(true);canvas.requestFocus();left=new Runnable(){public void run(){menu();}};footer(L.t("Opțiuni"),"7 / 9 Zoom",L.t("Înapoi"));}
    private void menu(){options(L.t("Document PDF"),new String[]{L.t("Mergi la pagina"),L.t("Salvează semn de carte"),L.t("Deschide semnul de carte"),L.t("Comenzi PDF")},new Choice(){public void pick(int at){if(at==0)jump();else if(at==1){getSharedPreferences("pdf-reader",0).edit().putInt(key+"-mark",page).apply();notice(L.t("Semn de carte salvat"));}else if(at==2){int mark=getSharedPreferences("pdf-reader",0).getInt(key+"-mark",-1);if(mark<0)notice(L.t("Niciun semn de carte"));else{page=Math.max(0,Math.min(count-1,mark));render();}}else notice(L.t("4 / 6: pagină. 7 / 9: zoom. Săgeți: deplasare. PDF-ul este afișat ca imagine; căutarea textului nu este disponibilă."));}});}
    private void jump(){LinearLayout f=fields(L.t("Mergi la pagina"));final EditText value=field(f,"1 – "+count,""+(page+1),InputType.TYPE_CLASS_NUMBER);left=new Runnable(){public void run(){try{int next=Integer.parseInt(value.getText().toString());if(next<1||next>count)throw new IllegalArgumentException();page=next-1;render();}catch(RuntimeException e){notice(L.t("Număr de pagină invalid"));}}};back=new Runnable(){public void run(){show();}};footer(L.t("Deschide"),"",L.t("Șterge"));value.requestFocus();}
    public boolean onKeyDown(int key,KeyEvent event){if(canvas!=null&&canvas.getParent()==root&&bitmap!=null){if(key==KeyEvent.KEYCODE_4||key==KeyEvent.KEYCODE_6){if(event.getRepeatCount()==0){page=CircularNavigation.step(page,key==KeyEvent.KEYCODE_4?-1:1,count);render();}return true;}if(key==KeyEvent.KEYCODE_7||key==KeyEvent.KEYCODE_9){if(event.getRepeatCount()==0){zoom=Math.max(1,Math.min(4,zoom+(key==KeyEvent.KEYCODE_9?1:-1)));panX=panY=0;canvas.invalidate();}return true;}if(key>=19&&key<=22){panX+=key==21?20:key==22?-20:0;panY+=key==19?20:key==20?-20:0;canvas.invalidate();return true;}}return super.onKeyDown(key,event);}
    protected void onPause(){save();super.onPause();}
    protected void onDestroy(){closed=true;generation++;if(bitmap!=null){bitmap.recycle();bitmap=null;}super.onDestroy();}
}
